function requireRole(...allowedRoles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ success: false, message: 'Authentication required' });
    }
    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({
        success: false,
        message: `Forbidden: Access restricted to [${allowedRoles.join(', ')}]. Current role: ${req.user.role}`
      });
    }
    next();
  };
}

async function calculateEventHealth(eventId) {
  const allTasks = await Task.find({ eventId }).populate('assignedTo', 'name phone').lean();
  const allIssues = await Issue.find({ eventId }).lean();
  const departments = await Department.find({ eventId }).populate('leaderId', 'name').lean();
  const now = new Date();

  // Dynamic query-time overdue evaluation
  const updatedTasks = allTasks.map(task => {
    const isOverdue = task.deadline && new Date(task.deadline) < now && task.status !== 'COMPLETED';
    let currentStatus = task.status;
    if (isOverdue && task.status !== 'OVERDUE' && task.status !== 'BLOCKED') {
      currentStatus = 'OVERDUE';
    }
    return { ...task, status: currentStatus, id: task._id.toString() };
  });

  const totalTasks = updatedTasks.length;
  const completedTasks = updatedTasks.filter(t => t.status === 'COMPLETED').length;
  const overdueTasks = updatedTasks.filter(t => t.status === 'OVERDUE').length;
  const blockedTasks = updatedTasks.filter(t => t.status === 'BLOCKED').length;

  const criticalIssues = allIssues.filter(i => i.status !== 'RESOLVED' && i.isEscalated === true);
  const openIssues = allIssues.filter(i => i.status !== 'RESOLVED');

  // Multi-factor qualitative health tier assignment
  let healthStatus = 'ON_TRACK';
  let healthLabel = '🟢 On Track';

  if (criticalIssues.length > 0 || blockedTasks >= 2) {
    healthStatus = 'CRITICAL';
    healthLabel = '🔴 Critical';
  } else if (overdueTasks > 0 || openIssues.length > 0 || blockedTasks === 1) {
    healthStatus = 'ATTENTION_NEEDED';
    healthLabel = '🟡 Attention Needed';
  }

  const overallProgress = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

  return {
    healthStatus,
    healthLabel,
    overallProgress,
    stats: { total: totalTasks, completed: completedTasks, overdue: overdueTasks, blocked: blockedTasks }
  };
}

function setupSocketIO(io) {
  io.on('connection', (socket) => {
    // Join incident chat room
    socket.on('join_issue_chat', ({ issueId, userId, userName, role }) => {
      if (!issueId) return;
      const room = `issue_${issueId}`;
      socket.join(room);
      socket.to(room).emit('user_joined_chat', { userId, userName, role, timestamp: new Date().toISOString() });
    });

    // Dispatch real-time chat message
    socket.on('send_issue_message', async ({ issueId, eventId, senderId, senderName, senderRole, message }) => {
      if (!message || !message.trim() || !issueId) return;

      try {
        const newMsg = await IssueMessage.create({
          issueId,
          senderId,
          senderName,
          senderRole,
          message: message.trim()
        });

        const formattedMsg = {
          ...newMsg.toObject(),
          id: newMsg._id.toString(),
          createdAt: newMsg.createdAt.toISOString()
        };

        // Broadcast message to everyone inside the incident room
        io.to(`issue_${issueId}`).emit('new_issue_message', formattedMsg);
        io.to(`issue_${issueId}`).emit('receive_issue_message', formattedMsg);
      } catch (err) {
        console.error('[Socket Error] send_issue_message failed:', err);
      }
    });

    // Relay typing indicators
    socket.on('typing_issue_chat', ({ issueId, userName, isTyping }) => {
      if (!issueId) return;
      socket.to(`issue_${issueId}`).emit('user_typing_status', { userName, isTyping });
    });
  });
}

// 1. Worker Starts Task
router.post('/:id/start', authMiddleware, async (req, res) => {
  const task = await Task.findById(req.params.id);
  if (!task) return res.status(404).json({ success: false, message: 'Task not found' });
  task.status = 'IN_PROGRESS';
  task.progress = 10;
  await task.save();
  res.json({ success: true, data: task });
});

// 2. Worker Submits Proof Photo
router.post('/:id/submit-proof', authMiddleware, async (req, res) => {
  const task = await Task.findById(req.params.id);
  const { proofImage, proofNotes } = req.body;
  task.status = 'PENDING_APPROVAL';
  task.progress = 90;
  task.proofImage = proofImage;
  task.proofNotes = proofNotes || '';
  task.submittedAt = new Date();
  await task.save();
  res.json({ success: true, data: task });
});

